import clsx from 'clsx';
import * as L from 'leaflet';

export const getCoordsFromLatLng = (
  latLon: L.LatLng,
): [number, number] | [number, number, number] =>
  latLon?.alt ? [latLon.lat, latLon.lng, latLon.alt] : [latLon.lat, latLon.lng];

import { formatAltitude } from '@helpers/formatHelper';

import style from './style.module.less';
import { getObstacleTitle } from '../../Obstacles/@helpers/obstacles.helper';
import { obstacleCategoryNameResource } from '../../Obstacles/@resources/obstacles.resource';
import { IObstacle } from '../../Obstacles/@types/obstacles.types';

export const isLine = (layer: L.Layer): boolean => layer instanceof L.Polyline;

export const isPoint = (layer: L.Layer): boolean => layer instanceof L.Marker;

export const getDivIcon = (): L.DivIcon => {
  return L.divIcon({
    className: style.simpleIcon,
    html: `<span class="${style.simpleIconCircle}"></span>`,
    iconSize: [8, 8],
    iconAnchor: [4, 4],
  });
};

export interface IMarkerStyles {
  opacity?: number;
  color?: string;
}

export const setMarkerStyles = (marker: L.Marker | null, options: IMarkerStyles) => {
  if (!marker) return;
  const markerElement = marker?.getElement()?.querySelector(`span`) as HTMLSpanElement;

  if (!markerElement) return;

  if (options.color) markerElement.style.color = options.color;
  if (options.opacity) markerElement.style.opacity = options.opacity.toString();
  markerElement.dataset.color = options.color;
  return marker;
};

export function setMarkerObstacle(marker: L.Marker, obstacle: IObstacle, inDistance = true) {
  const icon = L.divIcon({
    className: clsx('badge badge-danger', style.passIcon, { [style.secondaryPoint]: !inDistance }),
    html: `<span name="${obstacle.name}" altitude="${formatAltitude(obstacle.altitude)}" title="${getObstacleTitle(obstacle)}">${obstacleCategoryNameResource[obstacle.category]}</span>`,
    iconSize: [24, 12],
    iconAnchor: [24, 6],
  });
  marker.setIcon(icon);
}

export const getMarkerStyles = (marker: L.Marker | null): IMarkerStyles => {
  const options: IMarkerStyles = {};

  if (!marker) return options;
  const markerElement = marker?.getElement()?.querySelector(`span`) as HTMLSpanElement;
  if (!markerElement) return options;

  if (markerElement.dataset.color) options.color = markerElement.dataset.color;
  if (markerElement.style.opacity) options.opacity = +markerElement.style.opacity;

  return options;
};

export const applyMarkerActive = (marker: L.Marker, isActive = true) =>
  isActive
    ? marker.getElement()?.classList?.add?.(style.activeMarker)
    : marker.getElement()?.classList?.remove?.(style.activeMarker);
export const applyPolylineActive = (polyline: L.Polyline, isActive = true) =>
  isActive
    ? polyline.getElement()?.classList?.add?.(style.activePolyline)
    : polyline.getElement()?.classList?.remove?.(style.activePolyline);

export const getHighlightedPointIcon = (text: string): L.DivIcon => {
  return L.divIcon({
    html: `<span class="${style.highlightedIcon}" data-text="${text}"></span>`,
    iconSize: [0, 0],
    iconAnchor: [0, 0],
  });
};

type TextPathOrientation = 'flip' | 'perpendicular' | number;

interface TextPathOptions {
  /**
   * Specifies if the text should be repeated along the polyline.
   * @default false
   */
  repeat?: boolean | undefined;
  /**
   * Centers the text according to the polyline's bounding box.
   * @default false
   */
  center?: boolean | undefined;
  /**
   * Show text below the path.
   * @default false
   */
  below?: boolean | undefined;
  /**
   * Set an offset to position text relative to the polyline.
   * @default 0
   */
  offset?: number | undefined;
  /**
   * Rotate text.
   * @default 0
   */
  orientation?: TextPathOrientation | undefined;
  /**
   * Object containing the attributes applied to the text tag.
   * @see https://developer.mozilla.org/en-US/docs/Web/SVG/Element/text#attributes
   * @default {}
   */
  attributes?: Record<string, string> | undefined;
}

interface PolylineWithSetText extends L.Polyline {
  /**
   * Set the text to display over this Polyline.
   * @default null Represents no text.
   */
  setText: (text: string | null, options?: TextPathOptions) => void;
}
export const setPolylineText = (
  polyline: L.Polyline,
  text: string | null,
  options?: TextPathOptions,
) => {
  (polyline as PolylineWithSetText).setText(text, options);
};
