import { formatAltitude } from '@helpers/formatHelper';

import {
  obstacleTypeNameResource,
  obstacleCategoryNameResource,
} from '../@resources/obstacles.resource';
import { IObstacle } from '../@types/obstacles.types';

export const getObstacleTitle = (obstacle: IObstacle) => {
  const parts: string[] = [];

  parts.push(obstacleTypeNameResource[obstacle.type]);
  parts.push(obstacle.name);
  parts.push(obstacle.description);
  parts.push(obstacleCategoryNameResource[obstacle.category]);
  parts.push(formatAltitude(obstacle.altitude));

  return parts.join('\n');
};
